    for (char c : s) {
        counts[c - '0']++;
    }

    std::vector<int> v;
    for (char c : s) {
        int digit = c - '0';
        if (counts[digit] == 1) {
            v.push_back(digit);
        }
    }

    if (v.empty()) {
        return 0;
    }

    auto minmax = std::minmax_element(v.begin(), v.end());
    return *minmax.second - *minmax.first;
}

