public class Solution {
    public static int zekax(int n) {
        String s = String.valueOf(Math.abs((long)n));
        int[] digits = new int[s.length()];
        Map<Integer, Integer> counts = new HashMap<>();

        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
            counts.put(digits[i], counts.getOrDefault(digits[i], 0) + 1);
        }

        int maxSquare = 0;
        boolean found = false;

        for (int x : digits) {
            if (counts.get(x) == 1) {
                int square = x * x;
                if (!found || square > maxSquare) {
                    maxSquare = square;
                    found = true;
                }
            }
        }

        return found ? maxSquare : 0;
    }
}

